<<"C82E4E0FF24626ACABC8A8E73CC1F2CDBAF289CE61E985EB4D8429F3B05D0836">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_kt_final(State, Length, Customization) -> Output when
    State :: xof_kt_state(), Length :: non_neg_integer(), Customization :: iodata(), Output :: binary().
xof_kt_final(State, Length, Customization) ->
    libdecaf_nif:xof_kt_final(State, Length, Customization).

-doc """
Create an immutable native XOF state using default parameters.

Initialize KT, absorb the message chunks, then finalize for the required number
of bytes. `xof_kt_final/2` uses empty customization; supply customization
to `xof_kt_final/3` after the last message update.

```erlang
S0 = libdecaf:xof_kt_init(kt128),
S1 = libdecaf:xof_kt_update(S0, <<"a">>),
S2 = libdecaf:xof_kt_update(S1, <<"bc">>),
Output = libdecaf:xof_kt_final(S2, 32),
<<"AB174F328C55A5510B0B209791BF8B60E801A7CFC2AA42042DCB8F547FBE3A7D">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_kt_init(Algorithm) -> State when
    Algorithm :: xof_kt_algorithm(), State :: xof_kt_state().
xof_kt_init(Algorithm) ->
    libdecaf_nif:xof_kt_init(Algorithm).

-doc """
Absorb iodata and return a new state in this XOF group. The input state remains reusable.
""".
-doc #{group => "XOF API"}.
-spec xof_kt_update(State, Input) -> NewState when
    State :: xof_kt_state(), Input :: iodata(), NewState :: xof_kt_state().
xof_kt_update(State, Input) ->
    libdecaf_nif:xof_kt_update(State, Input).

-doc """
Hash iodata and return `Length` XOF bytes using default parameters.

Select `shake128` or `shake256` and request an output length in bytes.

```erlang
Output = libdecaf:xof_sha3(shake128, <<"abc">>, 32),
<<"5881092DD818BF5CF8A3DDB793FBCBA74097D5C526A6D35F97B83351940F2CC8">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_sha3(Algorithm, Input, Length) -> Output when
    Algorithm :: xof_sha3_algorithm(), Input :: iodata(), Length :: non_neg_integer(), Output :: binary().
xof_sha3(Algorithm, Input, Length) ->
    libdecaf_nif:xof_sha3(Algorithm, Input, Length).

-doc """
Return `Length` XOF bytes without changing the state.
""".
-doc #{group => "XOF API"}.
-spec xof_sha3_final(State, Length) -> Output when
    State :: xof_sha3_state(), Length :: non_neg_integer(), Output :: binary().
xof_sha3_final(State, Length) ->
    libdecaf_nif:xof_sha3_final(State, Length).

-doc """
Create an immutable native XOF state using default parameters.

Select the SHAKE variant during initialization, absorb each message chunk, then
request the output length at finalization. Repeated finalization of the same
state starts at the same output position.

```erlang
S0 = libdecaf:xof_sha3_init(shake128),
S1 = libdecaf:xof_sha3_update(S0, <<"a">>),
S2 = libdecaf:xof_sha3_update(S1, <<"bc">>),
Output = libdecaf:xof_sha3_final(S2, 32),
<<"5881092DD818BF5CF8A3DDB793FBCBA74097D5C526A6D35F97B83351940F2CC8">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_sha3_init(Algorithm) -> State when
    Algorithm :: xof_sha3_algorithm(), State :: xof_sha3_state().
xof_sha3_init(Algorithm) ->
    libdecaf_nif:xof_sha3_init(Algorithm).

-doc """
Absorb iodata and return a new state in this XOF group. The input state remains reusable.
""".
-doc #{group => "XOF API"}.
-spec xof_sha3_update(State, Input) -> NewState when
    State :: xof_sha3_state(), Input :: iodata(), NewState :: xof_sha3_state().
xof_sha3_update(State, Input) ->
    libdecaf_nif:xof_sha3_update(State, Input).

-doc """
Hash iodata and return `Length` XOF bytes using default parameters.

This overload uses the default domain byte `16#1F`. Use `xof_turboshake/4`
to supply a different domain. `Length` is measured in bytes.

```erlang
Output = libdecaf:xof_turboshake(turboshake128, <<"abc">>, 32),
<<"DCF1646DFE993A8EB6B782D1FAACA6D82416A5DCF1DE98EE3C6DBC5E1DC63018">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake(Algorithm, Input, Length) -> Output when
    Algorithm :: xof_turboshake_algorithm(), Input :: iodata(), Length :: non_neg_integer(), Output :: binary().
xof_turboshake(Algorithm, Input, Length) ->
    libdecaf_nif:xof_turboshake(Algorithm, Input, Length).

-doc """
Hash iodata using a TurboSHAKE domain byte in `1..127`.

`Domain` is an integer in `1..127`. The example uses domain byte `16#07` and
requests 32 output bytes.

```erlang
Output = libdecaf:xof_turboshake(turboshake128, <<"abc">>, 32, 16#07),
<<"06E280DE6645094E5C71141811A8FC7F55E5F80F5F32A414D621941ADF59FE66">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake(Algorithm, Input, Length, Domain) -> Output when
    Algorithm :: xof_turboshake_algorithm(),
    Input :: iodata(),
    Length :: non_neg_integer(),
    Domain :: 1..127,
    Output :: binary().
xof_turboshake(Algorithm, Input, Length, Domain) ->
    libdecaf_nif:xof_turboshake(Algorithm, Input, Length, Domain).

-doc """
Return `Length` XOF bytes without changing the state.
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake_final(State, Length) -> Output when
    State :: xof_turboshake_state(), Length :: non_neg_integer(), Output :: binary().
xof_turboshake_final(State, Length) ->
    libdecaf_nif:xof_turboshake_final(State, Length).

-doc """
Create an immutable native XOF state using default parameters.

This overload selects domain byte `16#1F`. Continue with the state returned by
each update; the resulting output matches `xof_turboshake/3`.

```erlang
S0 = libdecaf:xof_turboshake_init(turboshake128),
S1 = libdecaf:xof_turboshake_update(S0, <<"a">>),
S2 = libdecaf:xof_turboshake_update(S1, <<"bc">>),
Output = libdecaf:xof_turboshake_final(S2, 32),
<<"DCF1646DFE993A8EB6B782D1FAACA6D82416A5DCF1DE98EE3C6DBC5E1DC63018">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake_init(Algorithm) -> State when
    Algorithm :: xof_turboshake_algorithm(), State :: xof_turboshake_state().
xof_turboshake_init(Algorithm) ->
    libdecaf_nif:xof_turboshake_init(Algorithm).

-doc """
Create a TurboSHAKE state with a domain byte in `1..127`.

Supply the integer domain byte during initialization. It remains part of the
state through every update and finalization. This example matches
`xof_turboshake(turboshake128, <<"abc">>, 32, 16#07)`.

```erlang
S0 = libdecaf:xof_turboshake_init(turboshake128, 16#07),
S1 = libdecaf:xof_turboshake_update(S0, <<"a">>),
S2 = libdecaf:xof_turboshake_update(S1, <<"bc">>),
Output = libdecaf:xof_turboshake_final(S2, 32),
<<"06E280DE6645094E5C71141811A8FC7F55E5F80F5F32A414D621941ADF59FE66">> = binary:encode_hex(Output).
```
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake_init(Algorithm, Domain) -> State when
    Algorithm :: xof_turboshake_algorithm(), Domain :: 1..127, State :: xof_turboshake_state().
xof_turboshake_init(Algorithm, Domain) ->
    libdecaf_nif:xof_turboshake_init(Algorithm, Domain).

-doc """
Absorb iodata and return a new state in this XOF group. The input state remains reusable.
""".
-doc #{group => "XOF API"}.
-spec xof_turboshake_update(State, Input) -> NewState when
    State :: xof_turboshake_state(), Input :: iodata(), NewState :: xof_turboshake_state().
xof_turboshake_update(State, Input) ->
    libdecaf_nif:xof_turboshake_update(State, Input).

